INSERT INTO public.regulation_revisions VALUES (8, '管理情報提供', '管理情報提供様式の改訂', '管理情報提供様式において役員総数等の記載方法が改訂されました。', '管理組合役員数（理事総数及び監事総数）', '管理組合役員数（理事総数、監事総数）', '別添4', '別添4', '表記修正', '2025-08-16 04:55:08.094054', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (15, '駐車場充電設備', '電気自動車充電設備に関する駐車場規定', '駐車場使用細則における充電設備の設置と運用に関する規定が新設されました。', '（新設）', '電気自動車等用充電設備（以下「充電設備」という。）を設置する際には、充電設備の使用上のルールや使用料についても、併せて駐車場使用細則等に定めることが望ましい。また、設置時には充電設備の設置にかかる費用や、充電設備の運用及び維持費を誰がどの程度負担するかについてあらかじめ総会で決議をしておくことが望ましい。', '第15条', 'コメント第15条関係④', '新設', '2025-08-16 05:02:17.072173', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (1, '充電設備', '電気自動車充電設備の設置工事', '共用部分の変更における新たな工事項目として電気自動車充電設備の設置が追加されました。', '（新設）', 'カ）充電設備の設置工事に関し、充電器自体の設置及び配線を通すために必要な配管の設置など、建物の躯体部分や敷地への加工の程度が小さい工事を行う場合や、敷地へ相当程度の加工を加えることなく受変電設備を変更する場合は、普通決議により実施可能と考えられる。', '第47条', 'コメント第47条関係⑥カ', '新設', '2025-08-16 04:55:08.094054', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (2, '宅配ボックス設置', '宅配ボックス設置工事の詳細', '宅配ボックス設置工事の具体的な内容と決議要件が明確化されました。', '（新設）', 'エ）宅配ボックスの設置工事に関し、壁や床面に宅配ボックスを固定するなど、共用部分の加工の程度が小さい場合は、普通決議により実施可能と考えられる。', '第47条', 'コメント第47条関係⑥エ', '新設', '2025-08-16 04:55:08.094054', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (3, '外部専門家活用', '外部専門家を役員として選任', '組合員以外の外部専門家を理事や監事として選任可能になりました。', '役員は、組合員のうちから、総会で選任する。', '役員は、組合員のうちから、総会で選任する。ただし、細則で定めるところにより、組合員以外の者のうちから役員を選任することができる。', '第35条', '第35条', '追加', '2025-08-16 04:55:08.094054', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (4, '役員欠格条項', '役員の欠格条項の新設', '外部専門家活用に伴い、役員の欠格条項が新たに規定されました。', '（新設）', '次の各号のいずれかに該当する者は、役員となることができない。一 精神の機能の障害により役員の職務を適正に執行するに当たって必要な認知、判断及び意思疎通を適切に行うことができない者又は破産者で復権を得ない者 二 禁錮以上の刑に処せられ、その執行を終わり、又はその執行を受けることがなくなった日から５年を経過しない者 三 暴力団員等', '第36条の2', '第36条の2', '新設', '2025-08-16 04:55:08.094054', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (5, '監事機能強化', '監事の理事会出席義務化', '監事による監査機能強化のため、理事会への出席が義務化されました。', '監事は、理事会に出席し、必要があると認めるときは、意見を述べることができる。', '監事は、理事会に出席し、必要があると認めるときは、意見を述べなければならない。', '第41条', '第41条第4項', '義務化', '2025-08-16 04:55:08.094054', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (6, '電磁的方法活用', '議事録作成の電磁的記録対応', '議事録の作成・保管・閲覧において電磁的記録による方法が可能になりました。', '総会の議事については、議長は、議事録を作成しなければならない。', '総会の議事については、議長は、書面又は電磁的記録により、議事録を作成しなければならない。', '第49条', '第49条', '選択肢追加', '2025-08-16 04:55:08.094054', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (7, '組合員名簿管理', '組合員名簿・居住者名簿の作成義務', '組合員名簿と居住者名簿の作成・保管・閲覧に関する規定が新設されました。', '（新設）', '理事長は、組合員名簿及び居住者名簿（以下「組合員名簿等」という。）を作成して保管し、組合員の相当の理由を付した書面による請求があったときは、これらを閲覧させなければならない。', '第64条の2', '第64条の2', '新設', '2025-08-16 04:55:08.094054', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (9, '外部専門家活用詳細', '外部専門家活用パターンの改訂', '外部専門家の活用パターンにおける表現が改訂されました。', '従来どおり理事会を設け、理事会役員に外部専門家を選任するパターン。', '従来どおり理事会を設け、理事会役員に外部専門家を入れるパターン。', '別添1', '別添1', '表現修正', '2025-08-16 04:55:08.094054', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (10, '専有部分等', '専有部分の範囲に関する明確化', '専有部分の範囲について、より明確な定義が追加されました。', '各区分所有者の専有部分は、住戸番号○○号室（平面図に表示した部分）とする。', '各区分所有者の専有部分は、住戸番号○○号室（平面図に表示した部分）とする。ただし、構造上区分所有権の目的とすることができない建物の部分及び規約により共用部分とされた建物の部分は、専有部分に含まれない。', '第12条', '第12条', '明確化', '2025-08-16 05:01:54.205971', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (11, '専有部分の修繕', '専有部分の修繕に関する規定整備', '専有部分の修繕について、共用部分に影響を与える場合の手続きが明確化されました。', '区分所有者は、その専有部分について、修繕、模様替え又は増築を行うことができる。', '区分所有者は、その専有部分について、修繕、模様替え又は増築を行うことができる。ただし、専有部分の修繕が共用部分又は他の専有部分に影響を及ぼすおそれがある場合は、あらかじめ理事長の承認を得なければならない。', '第12条', 'コメント第12条関係', '明確化', '2025-08-16 05:01:54.205971', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (12, '使用細則', '使用細則における専有部分使用の詳細規定', '専有部分の使用に関する細則規定が詳細化されました。', '（既存の使用細則規定）', '専有部分の使用については、別に定める使用細則によるものとし、当該使用細則には専有部分における設備の設置基準、騒音防止、ペット飼育等に関する事項を定めるものとする。', '第12条', '使用細則', '詳細化', '2025-08-16 05:01:54.205971', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (13, '住宅宿泊事業', '住宅宿泊事業法の具体的明記', '住宅宿泊事業法における法律番号の明記により、より明確な規定となりました。', '区分所有者は、その専有部分を住宅宿泊事業法第３条第１項の届出を行って営む同法第２条第３項の住宅宿泊事業に使用することができる。', '区分所有者は、その専有部分を住宅宿泊事業法（平成２９年法律第６５号）第３条第１項の届出を行って営む同法第２条第３項の住宅宿泊事業に使用することができる。', '第12条', 'コメント第12条関係②', '明確化', '2025-08-16 05:02:17.072173', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (14, '住宅宿泊事業禁止', '住宅宿泊事業禁止規定の明確化', '住宅宿泊事業を禁止する場合の法的根拠がより明確になりました。', '区分所有者は、その専有部分を住宅宿泊事業法第３条第１項の届出を行って営む同法第２条第３項の住宅宿泊事業に使用してはならない。', '区分所有者は、その専有部分を住宅宿泊事業法（平成２９年法律第６５号）第３条第１項の届出を行って営む同法第２条第３項の住宅宿泊事業に使用してはならない。', '第12条', 'コメント第12条関係②', '明確化', '2025-08-16 05:02:17.072173', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (16, '修繕積立金管理', '修繕積立金の使途拡充', 'マンション再生手法（更新・除却等）の調査・設計段階の支出について修繕積立金を充当できる旨を整備し、修繕積立金の管理・運用に関する費用に修繕積立金を充当できる旨を明確化。また建替事業におけるプロセスによらず必要に応じて修繕積立金を取り崩すことも可能とし、建物の更新（一棟リノベーション）についても明確化', '第28条 管理組合は、各区分所有者が納入する修繕積立金を積み立てるものとし、積み立てた修繕積立金は、次の各号に掲げる特別の管理に要する経費に充当する場合に限って取り崩すことができる。
一 一定年数の経過ごとに計画的に行う修繕
二 不測の事故その他特別の事由により必要となる修繕
三 敷地及び共用部分等の変更
四 建物の建替え及びマンション敷地売却（以下「建替え等」という。）に係る合意形成に必要となる事項の調査
五 その他敷地及び共用部分等の管理に関し、区分所有者全体の利益のために特別に必要となる管理', '第28条 管理組合は、各区分所有者が納入する修繕積立金を積み立てるものとし、積み立てた修繕積立金は、次の各号に掲げる特別の管理に要する経費に充当する場合に限って取り崩すことができる。
一 一定年数の経過ごとに計画的に行う修繕
二 不測の事故その他特別の事由により必要となる修繕
三 敷地及び共用部分等の変更
四 建物の建替え及びマンション敷地売却、建物の更新、建物敷地売却、建物取壊し敷地売却又は取壊し（以下「マンション再生等」という。）に係る合意形成に必要となる事項の調査
五 修繕積立金の管理及び運用に要する費用
六 その他敷地及び共用部分等の管理に関し、区分所有者全体の利益のために特別に必要となる管理', '第28条', '§28', '改正', '2025-08-21 05:07:06.642721', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (17, '損害賠償請求権代理', '共用部分等に係る損害賠償請求権の代理行使', '損害賠償金等の使途を制限する規定を創設し、区分所有権譲渡時の別段意思表示を禁止し、理事長による区分所有者及び区分所有者であった者の損害賠償請求権代理行使を明示', '第24条 区分所有者は、共用部分等に関し、管理組合が火災保険、地震保険その他の損害保険の契約を締結することを承認する。
2 理事長は、前項の契約に基づく保険金額の請求及び受領について、区分所有者を代理する。', '第24条 区分所有者は、共用部分等に関し、管理組合が火災保険、地震保険その他の損害保険の契約を締結することを承認する。
2 区分所有者は、前項の契約に基づく保険金並びに敷地及び共用部分等について生じた損害賠償金及び不当利得による返還金（以下「保険金等」という。）について、その原因となる敷地及び共用部分等の損害又は瑕疵についてその修繕のため必要であるときは、当該修繕に要する費用に充当する。
3 区分所有者は、区分所有権を譲渡した場合において、区分所有法第26条第2項の規定に基づく別段の意思表示を行わない。
4 理事長は、前項の契約に基づく保険金等の請求及び受領について、区分所有者及び区分所有者であった者を代理する。', '第24条、第67条', '§24, §67', '改正', '2025-08-21 05:07:06.642721', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (18, '役員資格要件', '管理組合役員に選任可能な者の範囲の見直し', '管理組合の役員の担い手不足が指摘される中、区分所有者の家族・親族が役員に選任される事例を受け、家族・親族が役員に就任する場合の留意事項をコメントに追加', '第35条関係コメント
管理組合は、建物、敷地等の管理を行うために区分所有者全員で構成される団体であることを踏まえ、役員の資格要件を、当該マンションへの居住の有無に関わりなく区分所有者であるという点に着目して、「組合員」としている。', '第35条関係コメント
④ 管理組合の役員の担い手不足に対応するため、組合員の家族又は親族を選任できることとするように当該要件を緩和することも考えられる。この場合、「区分所有者の配偶者（婚姻の届出をしていないが事実上婚姻関係と同様の事情にある者を含む。）及び○親等以内の親族に限る」や「○○マンションに現に居住する組合員の同居家族に限る」のように、選任できる家族又は親族の範囲を明確化することが必要である。', '第35条', '§35コメント', 'コメント追加', '2025-08-21 05:07:06.642721', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (19, '役員欠格条項', '役員欠格条項の見直し', '会社法、一般社団法人法等の規定に合わせた欠格条項の再検討を行い、「禁錮」を「拘禁刑」に改正。成年被後見人等であることを理由に不当に差別されないよう令和元年に行われた欠格条項見直しに対応', '第36条の2 次の各号のいずれかに該当する者は、役員となることができない。
一 精神の機能の障害により役員の職務を適正に執行するに当たって必要な認知、判断及び意思疎通を適切に行うことができない者又は破産者で復権を得ない者
二 禁錮以上の刑に処せられ、その執行を終わり、又はその執行を受けることがなくなった日から5年を経過しない者
三 暴力団員等（暴力団員又は暴力団員でなくなった日から5年を経過しない者をいう。）', '第36条の2 次の各号のいずれかに該当する者は、役員となることができない。
一 精神の機能の障害により役員の職務を適正に執行するに当たって必要な認知、判断及び意思疎通を適切に行うことができない者又は破産者で復権を得ない者
二 拘禁刑以上の刑に処せられ、その執行を終わり、又はその執行を受けることがなくなった日から5年を経過しない者
三 暴力団員等（暴力団員又は暴力団員でなくなった日から5年を経過しない者をいう。）', '第36条の2', '§36の2', '改正', '2025-08-21 05:07:36.450073', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (20, '本人確認', '管理組合役員等の本人確認', '管理組合財産を狙った区分所有者ではない者による管理組合役員・専門委員へのなりすまし事案が発生したため、管理組合役員、専門委員就任時の本人確認についてコメントを追加。運転免許証、パスポート、マイナンバーカード等の顔写真付き身分証明書の提示を求める方法を提示', '（規定なし）', '【コメント】第35条関係
⑩ 役員は、マンションの敷地、共用部分等や管理費、修繕積立金といった組合員の共有の財産を管理し、管理業者との業務委託や修繕工事の工事請負契約といった多額の発注、契約に関する管理組合としての意思決定に直接的に関与することが想定される。そのため、部外者が役員になりすまし、役員の業務の適正な実施を妨害した場合、管理組合が多額の損害を被るおそれがあることから、そうした事態を防止するためには、役員候補者の本人確認を適切に実施することが有効と考えられる。', '第35条、第55条', '§35コメント、§55コメント', '新設', '2025-08-21 05:07:36.450073', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (21, '防災業務', '管理組合が取り組むべき防災関係業務の内容', 'マンションにおける防災対策の重要性が指摘される中、管理組合において取り組むべき防災関係業務の内容をコメントに追加。防災マニュアル作成、防災訓練実施、防災用名簿作成、防災物資備蓄等を明記', '（規定なし）', '【コメント】第32条関係
⑨ 第十二号に掲げる「マンション及び周辺の風紀、秩序及び安全の維持、防災並びに居住環境の維持及び向上に関する業務」のうち、「防災に関する業務」とは、平時から管理組合や区分所有者において進めるべき防災対策の取組である防災マニュアルの作成・周知、防災訓練の実施、防災情報の収集・周知、防災用名簿の作成、防災物資等の備蓄等が考えられる。なお、これらの取組については、管理組合が担うのではなく、別に防災組織を結成した上で、防災組織が主導して取り組むことも考えられる。', '第32条', '§32コメント', 'コメント追加', '2025-08-21 05:07:36.450073', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (22, '防火管理者', '防火管理者の選任', '消防法上設置が求められている防火管理者に関する規定の追加を検討し、マンションの居住人数が一定規模以上の場合（収容人数50名以上の集合住宅）における防火管理者選任規定を創設', '（規定なし）', '**（防火管理者の選任）**
第32条の2 理事長は、組合員のうちの一定の資格を有する者の中から防火管理者を選任し、その者に防火上必要な業務を行わせなければならない。
2 防火管理者が、消防署の指示、勧告等により施設の改善を申し入れたときは、理事長は、必要な措置を講じなければならない。', '第32条の2', '§32の2', '新設', '2025-08-21 05:07:36.450073', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (23, '喫煙ルール', 'マンション内での喫煙に関するルールの整備', '改正健康増進法に基づく基本方針において、令和14年度までに「望まない受動喫煙」をなくすことを目指すことから、管理組合において、喫煙に関するルールを定める際の留意事項をコメントに追加', '【コメント】第18条関係
① 使用細則で定めることが考えられる事項としては、動物の飼育やピアノ等の演奏に関する事項等専有部分の使用方法に関する規制や、駐車場、倉庫等の使用方法、使用料、置き配を認める際のルール等敷地、共用部分の使用方法や対価等に関する事項等が挙げられ、このうち専有部分の使用に関するものは、その基本的な事項は規約で定めるべき事項である。', '【コメント】第18条関係
① 使用細則で定めることが考えられる事項としては、動物の飼育やピアノ等の演奏に関する事項等専有部分の使用方法に関する規制や、駐車場、倉庫等の使用方法、使用料、置き配を認める際のルール、喫煙に関するルール等敷地、共用部分の使用方法や対価等に関する事項等が挙げられ、このうち専有部分の使用に関するものは、その基本的な事項は規約で定めるべき事項である。
⑥ 喫煙に関しては、共用部分（専用使用権が設定されている部分を含む。）においてそれを認める、認めない等の規定、認める場合において他の区分所有者及び占有者に受動喫煙被害を及ぼさないために守るべき事項、これらの事項に違反した者に対する措置等について、使用細則で定めることは可能である。また、共用部分での喫煙を認める場合のほか、専有部分における喫煙であっても、他の区分所有者及び占有者の望まない受動喫煙を防止する観点から、周囲の状況に配慮した方法で喫煙することが望ましく、使用細則において、そうした規定を盛り込むことも考えられる。', '第18条', '§18コメント', 'コメント追加', '2025-08-21 05:08:14.21602', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (24, '総会決議要件', '総会決議における多数決要件の見直し', '「特別決議」について総会出席者による多数決を可能とし、バリアフリー化による共用部分の変更等に係る決議の多数決要件を4分の3から3分の2に緩和', '第47条 総会の会議（WEB会議システム等を用いて開催する会議を含む。）は、前条第1項に定める議決権総数の半数以上を有する組合員が出席しなければならない。
2 総会の議事は、出席組合員の議決権の過半数で決する。
3 次の各号に掲げる事項に関する総会の議事は、前項にかかわらず、組合員総数の4分の3以上及び議決権総数の4分の3以上で決する。
一 規約の制定、変更又は廃止
二 敷地及び共用部分等の変更（その形状又は効用の著しい変更を伴わないもの及び建築物の耐震改修の促進に関する法律第25条第2項に基づく認定を受けた建物の耐震改修を除く。）
三 区分所有法第58条第1項、第59条第1項又は第60条第1項の訴えの提起
四 建物の価格の2分の1を超える部分が滅失した場合の滅失した共用部分の復旧', '第47条 総会の会議（WEB会議システム等を用いて開催する会議を含む。）は、前条第1項に定める議決権総数の半数以上を有する組合員が出席しなければならない。
2 総会の議事は、出席組合員の議決権の過半数で決する。
3 次の各号に掲げる事項に関する総会の議事は、前2項にかかわらず、組合員総数及び議決権総数の各半数以上を有する組合員の出席を要し、出席組合員及びその議決権の各4分の3以上で決する。
一 規約の制定、変更又は廃止
二 敷地及び共用部分等の変更（その形状又は効用の著しい変更を伴わないもの及び建築物の耐震改修の促進に関する法律第25条第2項に基づく認定を受けた建物の耐震改修を除く。）
三 敷地及び共用部分等の変更に伴って必要となる専有部分の管理
四 区分所有法第58条第1項、第59条第1項又は第60条第1項の訴えの提起
4 次の各号に掲げる事項に関する総会の議事は、前3項にかかわらず、組合員総数及び議決権総数の各半数以上を有する組合員の出席を要し、出席組合員及びその議決権の各3分の2以上で決する。
一 敷地及び共用部分等の変更又は敷地及び共用部分等の変更に伴って必要となる専有部分の管理のうち、共用部分の設置若しくは保存に瑕疵があることによって他人の権利若しくは法律上保護される利益が侵害され、若しくは侵害されるおそれがある場合における瑕疵の除去に関して必要となるもの及び高齢者、障害者等の移動若しくは施設の利用に係る身体の負担を軽減することにより、その移動若しくは施設の利用上の利便性及び安全性を向上させるために必要となるもの
二 建物の価格の2分の1を超える部分が滅失した場合の滅失した共用部分の復旧', '第47条', '§47', '改正', '2025-08-21 05:08:14.21602', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (25, '国内管理人', '国内管理人制度の活用に係る手続き', '「国内管理人」制度を区分所有者が活用する際の手続き規定等を創設。組合員が国内に居住していない場合に国内管理人の選任を義務付けることも可能', '（規定なし）', '**（国内管理人）**
第31条の3 組合員が、区分所有法第6条の2に規定する国内管理人を選任した場合は、直ちにその旨及び国内管理人の氏名又は名称並びに住所又は居所を書面により理事長に届け出なければならない。
2 組合員は、前項の規定により届け出た国内管理人の選任を終了させた場合又は届け出た内容に変更があった場合には、直ちにその旨を書面により届け出なければならない。', '第31条の3', '§31の3', '新設', '2025-08-21 05:08:39.977532', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (31, '区分所有者責務', '区分所有者の責務', '区分所有法においても「区分所有者の責務」が規定されたことに合わせ、標準管理規約における規定を見直し。「管理組合の構成員として相互に協力し」「適正かつ円滑な管理」という文言を追加', '**（区分所有者の責務）**
第20条 区分所有者は、対象物件について、その価値及び機能の維持増進を図るため、常に適正な管理を行うよう努めなければならない。', '**（区分所有者の責務）**
第20条 区分所有者は、管理組合の構成員として相互に協力し、対象物件について、その価値及び機能の維持増進を図るため、常に適正かつ円滑な管理を行うよう努めなければならない。', '第20条', '§20', '改正', '2025-08-21 05:09:20.686111', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (32, 'IT・デジタル化', 'ITシステム活用規定の追加', '令和7年の建物の区分所有等に関する法律改正により、ITシステム活用促進が法的要件となったため', '（規定なし）', '第○条　ITシステムの活用について
１　管理組合は、業務の効率化を図るため、デジタル技術を活用したシステムを導入することができる。
２　管理費の決済、会計処理、理事会議事録の作成等に関して、電子システムを利用することができる。', '30', '新設', 'addition', '2025-08-21 08:09:00.851261', NULL, '3125710f-b498-4949-86e2-b01bc9fcc13a');
INSERT INTO public.regulation_revisions VALUES (33, '電子決済', '電子決済システム導入規定', '法改正に伴うデジタル化推進要件への対応', '（規定なし）', '第○条　電子決済システムについて
１　管理費、修繕積立金の支払いは、電子決済システムを利用することができる。
２　電子決済に関する手数料は、管理組合が負担する。', '31', '新設', 'addition', '2025-08-21 08:09:00.851261', NULL, '3125710f-b498-4949-86e2-b01bc9fcc13a');
INSERT INTO public.regulation_revisions VALUES (26, '所在不明区分所有者', '所在等不明区分所有者の総会決議等からの除外手続き', '所在等不明区分所有者を総会決議等から除外する制度を管理組合として活用する際の手続き規定を創設。手続きに要する費用負担に関する関連規定等も整備', '（規定なし）', '**（所在等不明区分所有者の総会の決議等からの除外）**
第67条の3 理事長は、区分所有者の所在等が不明となり、又はその所在等を知ることができないときは、理事会の決議を経て、裁判所に対し、その区分所有者（以下「所在等不明区分所有者」という。）及びその議決権を総会の決議等から除外することを求める請求をすることができる。
2 前項の請求を受け、裁判所によって所在等不明区分所有者及びその議決権を総会の決議等から除外することを認める決定がされたときは、第44条第1項及び第47条第3項から第6項までの「組合員総数」を「組合員総数（第67条の3に定める裁判所の決定を受けた所在等不明区分所有者を除く。）」と読み替える。', '第67条の3', '§67の3', '新設', '2025-08-21 05:08:39.977532', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (27, '専有部分管理制度', 'マンションに特化した財産管理制度の活用', '「所在等不明専有部分管理制度」及び「管理不全専有部分管理制度」を管理組合として活用する際の手続き規定等を創設。手続きに要する費用負担に関する関連規定等も整備', '（規定なし）', '**（所有者不明専有部分管理人）**
第67条の4 理事長は、区分所有者を知ることができず、又はその所在を知ることができない専有部分（専有部分が数人の共有に属する場合にあっては、共有者を知ることができず、又はその所在を知ることができない専有部分の共有持分）について、共用部分又は他の専有部分の管理に支障を来す場合は、理事会の決議を経て、裁判所に対し、区分所有法第46条の2に基づく所有者不明専有部分管理命令を求める請求をすることができる。

**（管理不全専有部分管理人）**
第67条の5 理事長は、区分所有者による専有部分の管理が不適当であることによって他の区分所有者の権利又は法律上保護される利益が侵害され、又は侵害されるおそれがある場合は、理事会の決議を経て、裁判所に対し、区分所有法第46条の8に基づく管理不全専有部分管理命令を求める請求をすることができる。', '第67条の4、第67条の5', '§67の4、§67の5', '新設', '2025-08-21 05:08:39.977532', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (28, '立入り・保存権限', '他の区分所有者の専有部分の保存請求', '現行の規定では管理を行うために必要な範囲内における「立入り」のみ規定されているところ、補修工事の実施等の「保存行為」も含むよう規定を見直し。漏水発生元の専有部分の区分所有者に代わって漏水箇所の補修を行うことが可能に', '**（必要箇所への立入り）**
第23条 前2条により管理を行う者は、管理を行うために必要な範囲内において、他の者が管理する専有部分又は専用使用部分への立入りを請求することができる。
2 前項により立入りを請求された者は、正当な理由がなければこれを拒否してはならない。
3 前項の場合において、正当な理由なく立入りを拒否した者は、その結果生じた損害を賠償しなければならない。', '**（必要箇所への立入り等）**
第23条 前2条により管理を行う者は、管理を行うために必要な範囲内において、他の者が管理する専有部分若しくは専用使用部分への立入り又は自らこれに保存行為を実施することを請求することができる。
2 前項により立入り又は保存行為の実施を請求された者は、正当な理由がなければこれを拒否してはならない。
3 前項の場合において、正当な理由なく立入り又は保存行為の実施を拒否した者は、その結果生じた損害を賠償しなければならない。
4 前3項の規定にかかわらず、理事長は、災害、事故等が発生した場合であって、緊急に他の者が管理する専有部分又は専用使用部分への立入り又は保存行為の実施をしなければ、共用部分等又は他の専有部分に対して物理的に又は機能上重大な影響を与えるおそれがあるときは、その専有部分又は専用使用部分に自ら立ち入り、又は保存行為を実施することができる。', '第23条', '§23', '改正', '2025-08-21 05:09:20.686111', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (29, '総会招集通知', '総会招集時の通知事項等の見直し', '総会招集時の通知事項として、必ず「議案の要領」を示すよう規定を見直し。共用部分の変更に係る決議及びマンション再生決議において、多数決要件が緩和される場合には通知事項とし、マンション再生等に係る決議時に必要とする理由等の詳細な通知事項も整備', '第43条 総会を招集するには、少なくとも会議を開く日の2週間前（会議の目的が建替え決議又はマンション敷地売却決議であるときは2か月前）までに、会議の日時、場所（WEB会議システム等を用いて会議を開催するときは、その開催方法）及び目的を示して、組合員に通知を発しなければならない。
4 第1項の通知をする場合において、会議の目的が第47条第3項第一号、第二号若しくは第四号に掲げる事項の決議又は建替え決議若しくはマンション敷地売却決議であるときは、その議案の要領をも通知しなければならない。', '第43条 総会を招集するには、少なくとも会議を開く日の2週間前（会議の目的がマンション再生等に係る決議のいずれかであるときは2か月前）までに、会議の日時、場所（WEB会議システム等を用いて会議を開催するときは、その開催方法）及び目的及び議案の要領を示して、組合員に通知を発しなければならない。', '第43条', '§43', '改正', '2025-08-21 05:09:20.686111', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (30, '専有部分管理', '専有部分の使用等を伴う共用部分の管理', '現行の規定では、特段の手続き要件が設けられていないところ、改正区分所有法の規定に合わせ、「総会決議」を要件化', '**（敷地及び共用部分等の管理）**
第21条 敷地及び共用部分等の管理については、管理組合がその責任と負担においてこれを行うものとする。ただし、バルコニー等の保存行為（区分所有法第18条第1項ただし書の「保存行為」をいう。以下同じ。）のうち、通常の使用に伴うものについては、専用使用権を有する者がその責任と負担においてこれを行わなければならない。
2 専有部分である設備のうち共用部分と構造上一体となった部分の管理を共用部分の管理と一体として行う必要があるときは、管理組合がこれを行うことができる。', '**（敷地及び共用部分等の管理）**
第21条 敷地及び共用部分等の管理については、管理組合がその責任と負担においてこれを行うものとする。ただし、バルコニー等の保存行為（区分所有法第18条第1項ただし書の「保存行為」をいう。以下同じ。）のうち、通常の使用に伴うものについては、専用使用権を有する者がその責任と負担においてこれを行わなければならない。
2 専有部分である設備のうち共用部分と構造上一体となった部分の管理を共用部分の管理と一体として行う必要があるときは、総会の決議を経て、管理組合がこれを行うことができる。', '第21条', '§21', '改正', '2025-08-21 05:09:20.686111', '5584b0ff-6215-4511-9aa5-b7bfa13dae15', NULL);
INSERT INTO public.regulation_revisions VALUES (34, '総会・理事会', 'オンライン総会開催規定', '令和7年法改正によるオンライン総会開催の正式認可への対応', '（規定なし）', '第○条　オンライン総会について
１　総会は、Web会議システムを使用してオンラインで開催することができる。
２　オンライン参加者の本人確認方法は、別途定める。', '15', '第3項追加', 'addition', '2025-08-21 08:09:00.851261', NULL, '3125710f-b498-4949-86e2-b01bc9fcc13a');
INSERT INTO public.regulation_revisions VALUES (35, '文書管理', 'デジタル議事録管理', 'デジタル化推進法改正への対応', '紙面による議事録保管', '第○条　議事録のデジタル化
１　理事会および総会の議事録は、電子文書として作成・保管することができる。
２　電子署名による署名を有効とする。', '18', '第2項改訂', 'modification', '2025-08-21 08:09:00.851261', NULL, '3125710f-b498-4949-86e2-b01bc9fcc13a');
INSERT INTO public.regulation_revisions VALUES (36, 'AI・先端技術', 'AI活用による管理業務効率化', '令和7年AI活用促進法改正への準拠', '（規定なし）', '第○条　AI技術の活用
１　管理組合は、人工知能（AI）技術を活用した業務効率化システムを導入することができる。
２　個人情報保護に関する法令を遵守し、適切なセキュリティ対策を講じる。', '32', '新設', 'addition', '2025-08-21 08:09:00.851261', NULL, '3125710f-b498-4949-86e2-b01bc9fcc13a');
INSERT INTO public.regulation_revisions VALUES (37, '電子投票', '電子投票システム導入', '法改正による電子投票の法的有効化への対応', '書面または口頭による投票', '第○条　電子投票について
１　総会における議決権行使は、電子投票システムを利用することができる。
２　電子投票の有効性確保のため、本人認証システムを併用する。', '16', '第4項追加', 'addition', '2025-08-21 08:09:00.851261', NULL, '3125710f-b498-4949-86e2-b01bc9fcc13a');
INSERT INTO public.regulation_revisions VALUES (38, 'クラウド・ストレージ', 'クラウドストレージ活用規定', 'デジタル化推進およびテレワーク対応強化', '物理的保管のみ', '第○条　クラウドストレージの活用
１　管理組合の文書は、セキュリティが確保されたクラウドストレージサービスに保管することができる。
２　個人情報を含む文書については、暗号化等の追加的セキュリティ対策を講じる。', '33', '新設', 'addition', '2025-08-21 08:09:00.851261', NULL, '3125710f-b498-4949-86e2-b01bc9fcc13a');
INSERT INTO public.regulation_revisions VALUES (39, 'セキュリティ', 'スマートロック導入規定', 'セキュリティ強化とIoT活用推進', '物理鍵のみ', '第○条　スマートロックシステム
１　共用部分の施錠については、スマートロックシステムを導入することができる。
２　緊急時のアクセス方法を別途定める。', '34', '新設', 'addition', '2025-08-21 08:09:00.851261', NULL, '3125710f-b498-4949-86e2-b01bc9fcc13a');


